    "为电商产品视频提供内容与广告形式指导：先呈现一个具体的顾客困扰，再将产品定位为解决方案。适用于通过与基础痛点状态形成对比，最能体现产品价值的场景。": "إعلان يعرض مشكلة العميل ثم حل المنتج، ليبرز قيمته بالمقارنة.",
