    "为消费电子、数码小工具、手机配件、穿戴设备、充电器、相机、音频设备和互联产品创建高转化 AI 视频提示词，让功能、交互、连接和性能测试在镜头中真实运行。": "أوامر إعلانية للأجهزة والإكسسوارات تعرض الاستخدام والاتصال والأداء.",
    "为美容和个人护理产品创建高转化 AI 视频提示词，清楚呈现涂抹过程、产品质地、可见结果、自信与购买价值，同时保持声明安全合规。": "أوامر لإعلانات العناية والتجميل تعرض القوام والاستخدام والنتائج بادعاءات منضبطة.",
