    "根据产品图、品牌资料、服务内容和卖点，策划并生成具有完整人物、冲突、转折和情绪价值的剧情 TVC 广告片，可输出创意概念、人物设定、剧情脚本、分镜和 AI 视频提示词。": "إعلان قصصي من مواد العلامة، مع فكرة وشخصيات ونص ومشاهد وأوامر فيديو.",
    "面向高奢时尚、运动、汽车和 3C 品牌，策划具有国际大牌调性的情绪 TVC 全球广告宣传片。": "إعلان عالمي فاخر للأزياء والرياضة والسيارات والتقنية.",
    "创作拟人萌宠博主自媒体视频，将猫、狗、兔子、仓鼠、鸟类等动物塑造成具有固定人设、穿搭、声音和拍摄习惯的短视频博主。": "حيوانات أليفة كصنّاع محتوى، بشخصية وزي وصوت وأسلوب ثابت.",
    "创作搞笑故事视频，通过误会、身份反转、因果升级、冷幽默、道具反转或规则漏洞制造笑点。": "قصص مضحكة بسوء الفهم والمفاجآت والمفارقات.",
    "适用于短视频、微电影和 Vlog 等真人叙事创作，通过呼吸感手持与跟拍运镜生成音画同步短片，增强镜头代入、情绪张力和真实质感。": "مقاطع سردية بصوت وصورة متزامنين، وتصوير محمول واقعي وغامر.",
    "以 FPV 穿越机第一人称视角为核心，模拟俯冲、贴地穿隙、螺旋环绕和急速穿梭等动态运镜，生成具有速度感、空间穿透感和沉浸感的视频。": "فيديو FPV غامر بالغوص والطيران المنخفض والدوران السريع.",
