    "把产品或服务的核心卖点、使用场景、用户收益和行动引导转化为清晰有吸引力的 MG 营销视频。": "موشن جرافيك تسويقي يوضح المزايا والاستخدام والفائدة.",
    "把抽象知识、复杂概念和专业信息拆解成易理解的结构，通过图标、信息图和 MG 动效完成清晰讲解。": "تبسيط المعرفة والمفاهيم بالرسوم والأيقونات والحركة.",
    "把课程目标、知识结构、教学步骤和重点内容转化为节奏清楚、便于学习和复习的 MG 教学视频。": "دروس موشن جرافيك منظمة للأهداف والخطوات والمراجعة.",
    "把政策依据、适用对象、办理条件、材料步骤和官方渠道转化为准确、庄重、易懂的 MG 公共服务视频。": "شرح الخدمات العامة وشروطها ووثائقها وقنواتها الرسمية.",
    "使用数字人口播讲清商品定位、核心卖点、使用场景、优惠信息与行动引导，生成可直接播放和下载的营销视频节点。": "مقدّم افتراضي يشرح المنتج ومزاياه وعروضه في فيديو قابل للتنزيل.",
    "围绕个人定位、观点表达、知识分享和内容栏目，生成具有人设一致性、自然语气与稳定镜头表现的数字人口播视频。": "مقدّم افتراضي ثابت الهوية لمشاركة الآراء والمعرفة بأسلوب طبيعي.",
