    "项目督察": "مراقب المشروع",
    "星辉计划幕后监督者，推动新一轮能力筛选。": "المشرف السري على مشروع النجوم، يدفع نحو جولة جديدة لاختيار أصحاب القدرات.",
    "冷静强势，以计划成果为先，不惜牺牲学生。": "هادئ وحازم؛ يضع نتائج المشروع أولًا ولو على حساب الطلاب.",
    "向校长下达销毁记录的命令，与林宇的调查直接对立。": "يأمر المدير بإتلاف السجلات، ويقف مباشرة ضد تحقيق لين يو.",
    "低沉冷硬，语速缓慢，命令简短而明确。": "صوت عميق وبارد، بإيقاع بطيء وأوامر موجزة وواضحة.",
    "值日生": "طالب المناوبة",
    "负责放学后走廊清洁的普通学生。": "طالب عادي يتولى تنظيف الممر بعد الدوام.",
    "直率热心，面对异常既好奇又胆怯。": "صريح ومتعاون؛ يجمع بين الفضول والخوف أمام الظواهر الغريبة.",
    "偶遇林宇和张曼，提供实验楼蓝光出现的时间。": "يلتقي لين يو وتشانغ مان مصادفة، ويحدد وقت ظهور الضوء الأزرق بالمختبر.",
    "轻快的少年声线，紧张时说话稍快。": "صوت فتى خفيف وحيوي، يتسارع قليلًا عند التوتر.",
    "食堂阿姨": "عاملة المقصف",
    "星辉高中食堂晚餐窗口工作人员。": "عاملة نافذة العشاء في مقصف مدرسة النجوم.",
    "爽朗健谈，细心记得师生用餐习惯。": "مرحة واجتماعية، تتذكر بدقة عادات الطلاب والمعلمين في الطعام.",
    "向张曼随口提起校长深夜留校的见闻。": "تذكر لتشانغ مان عابرًا أن المدير بقي بالمدرسة حتى وقت متأخر.",
    "温厚响亮，语气自然，带生活气息。": "صوت دافئ وواضح، بنبرة طبيعية وقريبة من الحياة اليومية.",
    "校门口快递员": "مندوب التوصيل",
    "负责学校片区投递的快递员。": "مندوب مسؤول عن تسليم الطرود في منطقة المدرسة.",
