    "平视侧面缓慢推近，焦点停在克洛伊眼神": "اقتراب جانبي بطيء بمستوى العين، يثبت على نظرة كلوي",
    "沿既有视线平移，保持同侧轴线": "حركة أفقية على خط النظر مع الحفاظ على المحور",
    "侧面中景切手部特写，连续跟随戴戒动作": "من لقطة جانبية متوسطة إلى اليدين، مع متابعة وضع الخاتم",
    "动作匹配切至正面，静止收束": "قطع مطابق للحركة إلى الأمام ثم ثبات",
    "暖金吊灯映亮长桌，克洛伊面部渐落入冷影，空气骤然凝滞。": "ثريا ذهبية تضيء الطاولة، ويغمر ظل بارد وجه كلوي، فيسود التوتر.",
    "宴会低语渐弱，杯盘轻碰；低沉悬念音缓缓起。": "تخفت همسات الحفل مع رنين الأواني، وتتصاعد موسيقى غموض منخفضة.",
    "校董席上方硬质侧光切出深重阴影，压迫感增强。": "ضوء جانبي حاد فوق مقاعد الإدارة يرسم ظلالًا ثقيلة ويزيد الضغط.",
    "压低的质问声贴近收音；背景人群窃语与弦乐低音持续。": "سؤال خافت وقريب، مع همسات الجمهور ووتريات منخفضة في الخلفية.",
    "柔暖烛光掠过双手，银戒闪出短促高光，背景虚化成金色光斑。": "شموع دافئة على اليدين، ولمعة خاطفة للخاتم وخلفية ذهبية ضبابية.",
    "衣料细响、指尖摩擦与戒指轻响；心跳声逐渐清晰。": "حفيف قماش واحتكاك أصابع ورنين خاتم، مع نبض يتضح تدريجيًا.",
    "正面聚光锁住两人，宾客席压暗，明暗反差定格宣告瞬间。": "ضوء أمامي يثبت الشخصين، ويظلم الضيوف لتأكيد لحظة الإعلان.",
    "宣告声清晰回荡；全场倒吸气与零星惊呼后骤然静默。": "يتردد الإعلان بوضوح؛ شهقات وصرخات قليلة يعقبها صمت مفاجئ.",
    "星辉高中表面是一所培养优秀学生的寄宿学校，暗中却通过“星辉计划”筛选能感知异常频率的少年。转学生林宇在新学期意外觉醒吸收与反射能量的能力，并与同桌张曼从一段失真的广播开始，逐步揭开十七年前校园实验事故的真相。八集故事以校园悬疑为骨架，让友情、身份谜团与能力失控彼此推进，最终将一所学校的秘密扩展成更大的危机。": "تبدو مدرسة النجوم مدرسة داخلية للمتفوقين، لكنها تختار سرًا عبر «مشروع النجوم» مراهقين يدركون ترددات شاذة. يستيقظ لدى الطالب المنتقل لين يو استعداد لامتصاص الطاقة وعكسها. ومن بث مشوه، يبدأ مع زميلته تشانغ مان كشف حقيقة حادث مختبر وقع قبل سبعة عشر عامًا. تتشابك الصداقة والهوية وفقدان السيطرة على القدرات في ثماني حلقات، لتتحول أسرار المدرسة إلى أزمة أوسع.",
    "故事发生在近未来的星辉市。少数青少年能感知一种被称为“星频”的异常能量，情绪波动会让能力被动觉醒。星辉高中表面是封闭式重点学校，地下却运行着筛选、记录并控制星频能力者的“星辉计划”；旧实验楼、校园广播和能力测评系统共同构成计划的监测网络。能力越强，使用者失去部分记忆的风险越高，而十七年前的实验事故正是所有规则与秘密的起点。": "تدور القصة في مدينة النجوم في المستقبل القريب. يدرك بعض المراهقين طاقة شاذة تسمى «تردد النجوم»، وتوقظ تقلباتهم العاطفية قدراتهم دون إرادة. تبدو المدرسة مؤسسة متفوقة ومغلقة، لكنها تدير مشروعًا لاختيار أصحاب هذه القدرات وتسجيلهم والسيطرة عليهم. يشكل المختبر القديم والإذاعة ونظام التقييم شبكة المراقبة. وكلما اشتدت القدرة ارتفع خطر فقدان الذاكرة. ويعود أصل القواعد والأسرار كلها إلى حادث المختبر قبل سبعة عشر عامًا.",
    "平凡少年林宇转学至异能者云集的星辉高中。面对陌生的环境和冷淡的同学，他体内的特殊能力在班主任介绍下悄然觉醒，正式开启了校园生活。与此同时，他尚未察觉体内潜藏的强大异能，而这场转学正是他揭开异能觉醒阴谋、从平凡走向非凡的命运起点。": "ينتقل الفتى العادي لين يو إلى مدرسة النجوم التي تجمع أصحاب القدرات. وسط مكان غريب وزملاء باردين، تستيقظ قوته بهدوء أثناء تقديم معلم الصف له. يجهل بعدُ حجم ما يخفيه، لكن انتقاله يبدأ رحلة كشف مؤامرة الاستيقاظ والعبور من حياة عادية إلى مصير استثنائي.",
    "平凡少年林宇转学至异能者云集的星辉高中。面对陌生的环境和冷淡的同学，他体内的特殊能力在班主任介绍下悄然觉醒，正式开启校园生活。与此同时，他尚未察觉体内潜藏的强大异能，而这场转学正是他揭开异能觉醒阴谋、从平凡走向非凡的命运起点。": "ينتقل الفتى العادي لين يو إلى مدرسة النجوم التي تجمع أصحاب القدرات. وسط مكان غريب وزملاء باردين، تستيقظ قوته بهدوء أثناء تقديم معلم الصف له. يجهل بعدُ حجم ما يخفيه، لكن انتقاله يبدأ رحلة كشف مؤامرة الاستيقاظ والعبور من حياة عادية إلى مصير استثنائي.",
    "林宇在开学第一天进入星辉高中，先以旁观者身份观察班级气氛，随后在课间冲突中被迫卷入异能波动。班主任表面维持秩序，实际在试探他的反应；风衣男则通过监控确认林宇的体质与旧实验记录吻合。本集以林宇听见实验楼低频声作为收束，为后续追查埋下线索。": "يراقب لين يو صفه في أول يوم، ثم يجرفه شجار الاستراحة إلى اضطراب القدرات. يحافظ المعلم على النظام ظاهرًا ويختبر استجابته، فيما يؤكد رجل المعطف عبر المراقبة تطابقه مع سجل تجربة قديمة. تنتهي الحلقة بصوت منخفض من المختبر يسمعه لين يو، فاتحًا باب التحقيق.",
    "16 岁高中生，安静克制却十分敏锐。": "طالب في السادسة عشرة، هادئ ومتحفظ وحاد الملاحظة.",
    "卷入校园谜团，执着追寻失踪真相。": "ينخرط في لغز المدرسة ويصر على كشف حقيقة الاختفاء.",
    "成绩优秀却性格疏离的同班同学。": "زميلة متفوقة لكنها متحفظة وبعيدة.",
    "因母亲旧案，与林宇共同追查校园真相。": "تتعاون مع لين يو لكشف أسرار المدرسة بسبب قضية أمها.",
    "表面严谨克制，始终留意学生异能反应。": "دقيق ومتحفظ ظاهرًا، يراقب دائمًا استجابات قدرات الطلاب.",
    "知晓部分旧事，在保护与隐瞒间摇摆。": "يعرف جزءًا من الماضي ويتردد بين الحماية والكتمان.",
    "身份成谜的监察者，长期潜伏在校园暗处。": "مراقب غامض الهوية يتخفى في ظلال المدرسة.",
    "持续追踪林宇，真实立场尚未明朗。": "يتعقب لين يو باستمرار، وموقفه الحقيقي مجهول.",
