    "外，日，海岛猎场主街": "خارجي، نهار، الشارع الرئيسي لجزيرة الصيد",
    "新增分场": "إضافة مشهد",
    "请输入该场的剧本": "اكتب نص هذا المشهد",
    "请输入剧本或在左侧说明要新增的内容": "اكتب النص أو صف الإضافة في المحادثة",
