    "普通画面": "مشهد عادي",
    "对口型": "مزامنة الشفاه",
    "中景，平视视角": "لقطة متوسطة بمستوى العين",
    "近景，低角度仰拍": "لقطة قريبة بزاوية منخفضة",
    "缓慢推镜头，聚焦林宇局促的神态": "اقتراب بطيء نحو توتر لين يو",
    "极速推进，强化威严感": "اقتراب خاطف يبرز الهيبة",
    "林宇背着一个边缘磨损的旧书包站在讲台旁，校服下摆微微泛白。新班级的视线落在他身上时，他第一次感到体内有细小的电流回应着周围的异能波动。": "يقف لين يو قرب المنصة بحقيبة بالية وزي به أطراف باهتة. حين تتجه إليه أنظار الصف يشعر لأول مرة بتيار صغير يستجيب لقدرات من حوله.",
    "林宇背着一个边缘磨损的旧书包，局促地站在讲台旁边，他的双手不安地揪着校服下摆，指节微微泛白。": "يقف لين يو متوترًا قرب المنصة بحقيبة بالية، ويشد طرف زيه بيدين قلقتين حتى تبيض مفاصله.",
    "Mr. Harris面无表情地站在讲台后，右手用力敲击木质桌面，发出沉闷的撞击声。": "يقف السيد هاريس جامد الوجه خلف المنصة، ويضرب الطاولة الخشبية بيمناه فيصدر صوت مكتوم.",
    "新入校的转学生，外表拘谨但体内异能即将被唤醒。": "طالب جديد متحفظ، وقدرته الخفية توشك أن تستيقظ.",
    "站在讲台侧方引导介绍，观察林宇的细微反应。": "يقف بجانب المنصة للتقديم ويراقب أدق استجابات لين يو.",
    "同班学生": "زملاء الصف",
    "用好奇和审视的目光打量新同学。": "يراقبون الطالب الجديد بفضول وتفحص.",
    "讲台、课桌和窗外光线形成觉醒前的日常空间。": "منصة ومقاعد وضوء نافذة يرسمون الحياة العادية قبل الاستيقاظ.",
    "讲台旁": "بجانب المنصة",
    "林宇第一次感到异能波动的位置。": "حيث يشعر لين يو باضطراب قدرته لأول مرة.",
    "教室后排": "خلف الصف",
    "学生视线聚集，制造轻微压迫感。": "تلتقي أنظار الطلاب لتخلق ضغطًا خفيفًا.",
    "时长 9s ｜ 镜头：中景推近 ｜ 场景：教室讲台": "المدة 9s · اقتراب متوسط · منصة الصف",
    "时长 9s ｜ 镜头：中景推近 ｜ 场景：星辉高中教室": "المدة 9s · اقتراب متوسط · صف مدرسة النجوم",
    "林宇（@图片 1，音色参考 @音频 1）在星辉高中教室（@图片 2）清晨自然光下背着旧书包站在讲台旁，镜头从学生视线切到他的手部特写。校服下摆微微泛白，周围同学保持距离，画面清冷克制，带轻微异能波动的空气闪烁。": "يقف لين يو (@صورة 1، مرجع الصوت @صوت 1) قرب منصة صف مدرسة النجوم (@صورة 2) في ضوء الصباح، حاملًا حقيبته القديمة. تنتقل الكاميرا من أنظار الطلاب إلى لقطة قريبة ليديه. زيه باهت الأطراف، وزملاؤه يحافظون على مسافة. الجو بارد ومتحفظ مع وميض خفيف لاضطراب الطاقة.",
    "平凡少年林宇转学至星辉高中。面对陌生环境和冷淡同学，他体内潜藏的特殊能力在班主任介绍下悄然觉醒，正式开启校园生活。": "ينتقل لين يو العادي إلى مدرسة النجوم. وسط مكان غريب وزملاء باردين، تستيقظ قدرته الخفية أثناء تقديم المعلم له، وتبدأ حياته المدرسية.",
    "视觉风格描述：采用清新明亮的日漫校园风格，强调现代校园的通透感与青春气息。": "أسلوب أنمي مدرسي ياباني مشرق وخفيف، يؤكد شفافية المكان وروح الشباب.",
    "林宇按照新的线索来到校史馆，在封存展柜里发现几页缺失的旧资料。资料编号与实验楼设备编号能够对应，校方曾经刻意把多起异常事故伪装成普通安全事件。": "يتبع لين يو دليلًا إلى متحف المدرسة ويكتشف صفحات مفقودة من وثائق مختومة. تتطابق أرقامها مع أجهزة المختبر، ويتبين أن الإدارة أخفت حوادث شاذة بوصفها حوادث سلامة عادية.",
    "基础画风风格词：学院悬疑、低饱和日漫、旧档案质感。": "الأسلوب: غموض أكاديمي وأنمي قليل التشبع وملمس أرشيف قديم.",
    "视觉风格描述：校史馆采用对称构图、玻璃反射和柔和顶光，表面整洁但细节处隐藏裂痕；缺页边缘、胶带痕迹和褪色照片作为关键视觉线索。": "تكوين متناظر وانعكاس زجاجي وضوء علوي ناعم؛ مظهر مرتب تشوبه فجوات. حواف الصفحات وآثار الشريط والصور الباهتة أدلة بصرية مهمة.",
    "从被动卷入变成主动追查，开始用异能感知旧资料中的异常波动。": "يبدأ التحقيق بنفسه ويستخدم قدرته لاستشعار اضطراب الوثائق القديمة.",
    "负责比对旧照片和病历编号，逐渐意识到母亲并非旁观者。": "تقارن الصور بأرقام الملفات الطبية، وتدرك أن أمها لم تكن مجرد شاهدة.",
    "表面维护学校荣誉，暗中控制所有档案入口。": "يحمي سمعة المدرسة ظاهرًا ويتحكم بمداخل الأرشيف سرًا.",
    "展柜、奖杯和旧照片构成看似光鲜的历史空间。": "خزائن وكؤوس وصور قديمة ترسم تاريخًا لامعًا في الظاهر.",
    "档案展柜": "خزانة الأرشيف",
    "缺页边缘和胶带痕迹成为关键证据。": "حواف الصفحات المفقودة وآثار الشريط دليلان حاسمان.",
    "长走廊与木门强调权力边界和压迫感。": "ممر طويل وباب خشبي يبرزان حدود السلطة والضغط.",
    "林宇在校史馆参观时感到展柜中传来微弱共振，张曼发现旧照片里有被裁掉的人影。两人沿着资料编号追查到实验楼设备清单，确认多年前的“安全事故”其实都与星辉计划有关。结尾校长站在监控画面前，删除了校史馆访问记录，但林宇已经把缺页边缘的编号记了下来。": "يحس لين يو رنينًا خفيفًا في خزانة المتحف، وتلاحظ تشانغ مان شخصًا قُص من صورة قديمة. تقودهما الأرقام إلى قائمة أجهزة المختبر، فيؤكدان ارتباط «حوادث السلامة» بمشروع النجوم. يحذف المدير سجل الزيارة، لكن لين يو حفظ الرقم على حافة الصفحة المفقودة.",
    "男生 20岁左右 音色清爽 倔强不服输": "شاب نحو العشرين، بصوت صافٍ وشخصية عنيدة لا تستسلم",
    "你好，我的声音，为你演尽喜怒哀乐。": "مرحبًا، بصوتي أؤدي لك الفرح والغضب والحزن والسعادة.",
