    "有穿帮问题，请检查人物服装与前一镜的衔接。": "هناك خطأ استمرارية؛ راجع الملابس مقارنة باللقطة السابقة.",
    "这一段转场稍快，建议多留半秒再切换镜头。": "الانتقال سريع قليلًا؛ أضف نصف ثانية قبل القطع.",
