    "入场镜头的视线方向与前一镜不一致，请再确认人物位置。": "اتجاه النظر مختلف عن اللقطة السابقة؛ راجع مواضع الشخصيات.",
    "人物转身后的动作衔接有跳帧感，请复核这一处过渡。": "تبدو حركة الالتفات متقطعة؛ راجع الانتقال.",
    "这一镜的背景色温与前后画面不同，请统一整体观感。": "حرارة لون الخلفية مختلفة؛ وحّدها مع اللقطات المجاورة.",
    "字幕和背景音乐已更新，请复核这一段。": "حُدّثت الترجمة والموسيقى؛ راجع هذا المقطع.",
    "此处对白结束后留白稍短，建议让情绪多停留半秒。": "الوقفة بعد الحوار قصيرة؛ أضف نصف ثانية للمشاعر.",
