    "Enter a custom value": "请输入自定义内容",
    "Paste a webpage URL to reference": "请填入想要参考的网页链接",
    "Clear white-background images work best; multiple angles supported": "清晰的白底图效果最佳，支持多角度",
    "Product, scene, and feature-detail images": "产品图、场景图、功能细节图等",
    "Upload a finished or competitor video for pacing and visual reference": "可上传成片或竞品视频，用于参考镜头节奏与画面表达",
    "Organize your video direction, content structure, and shots around your creative goal to quickly develop an editable video plan.": "根据创作目标整理视频方向、内容结构与镜头表达，快速形成可继续编辑的视频创作方案。",
    "Guide the content and format of ecommerce product videos: introduce a specific customer problem, then position the product as the solution. Ideal for showing product value through a clear before-and-after contrast.": "为电商产品视频提供内容与广告形式指导：先呈现一个具体的顾客困扰，再将产品定位为解决方案。适用于通过与基础痛点状态形成对比，最能体现产品价值的场景。",
    "Extract product information and available assets from a product URL to quickly create an ad video for ecommerce campaigns.": "根据商品链接提取产品信息与可用素材，快速生成适合电商投放的广告视频。",
    "Create high-converting AI video prompts for consumer electronics, gadgets, phone accessories, wearables, chargers, cameras, audio gear, and connected products. Show features, interactions, connectivity, and performance tests working on camera.": "为消费电子、数码小工具、手机配件、穿戴设备、充电器、相机、音频设备和互联产品创建高转化 AI 视频提示词，让功能、交互、连接和性能测试在镜头中真实运行。",
    "Create high-converting AI video prompts for beauty and personal care products. Clearly show application, texture, visible results, confidence, and purchase value while keeping claims safe and compliant.": "为美容和个人护理产品创建高转化 AI 视频提示词，清楚呈现涂抹过程、产品质地、可见结果、自信与购买价值，同时保持声明安全合规。",
    "Create high-converting AI video prompts for clothing, shapewear, underwear, loungewear, tops, shorts, dresses, and sets. Make fit, silhouette, fabric, styling confidence, and social proof visible.": "为服装、塑身衣、内衣、家居服、上衣、短裤、连衣裙和多件套创建高转化 AI 视频提示词，让版型、轮廓、面料表现、穿搭自信和社会认同可见。",
    "Plan and generate story-driven TV commercials from product images, brand materials, services, and selling points. Develop characters, conflict, twists, and emotional value, with creative concepts, character profiles, scripts, storyboards, and AI video prompts.": "根据产品图、品牌资料、服务内容和卖点，策划并生成具有完整人物、冲突、转折和情绪价值的剧情 TVC 广告片，可输出创意概念、人物设定、剧情脚本、分镜和 AI 视频提示词。",
    "Plan emotionally engaging global TV commercials with a premium international brand aesthetic for luxury fashion, sports, automotive, and consumer technology brands.": "面向高奢时尚、运动、汽车和 3C 品牌，策划具有国际大牌调性的情绪 TVC 全球广告宣传片。",
    "Create anthropomorphic pet influencer videos, turning cats, dogs, rabbits, hamsters, birds, and other animals into creators with consistent personalities, outfits, voices, and filming habits.": "创作拟人萌宠博主自媒体视频，将猫、狗、兔子、仓鼠、鸟类等动物塑造成具有固定人设、穿搭、声音和拍摄习惯的短视频博主。",
    "Create funny story videos using misunderstandings, identity reversals, escalating consequences, dry humor, prop twists, or loopholes to deliver the laughs.": "创作搞笑故事视频，通过误会、身份反转、因果升级、冷幽默、道具反转或规则漏洞制造笑点。",
    "Create live-action narratives for short videos, short films, and vlogs. Use natural handheld and follow-camera movement to produce synchronized audiovisual scenes with immersion, emotional tension, and realism.": "适用于短视频、微电影和 Vlog 等真人叙事创作，通过呼吸感手持与跟拍运镜生成音画同步短片，增强镜头代入、情绪张力和真实质感。",
    "Create immersive first-person FPV drone videos with dives, low-altitude gap flying, spiral orbits, and rapid fly-throughs for a strong sense of speed and space.": "以 FPV 穿越机第一人称视角为核心，模拟俯冲、贴地穿隙、螺旋环绕和急速穿梭等动态运镜，生成具有速度感、空间穿透感和沉浸感的视频。",
    "Explain who a company is, what it does, why it is trustworthy, and what to do next in a professional, credible motion graphics brand video.": "把企业是谁、做什么、为什么值得信任以及下一步行动讲清楚，形成专业、可信、有品牌辨识度的企业 MG 宣传视频。",
    "Turn product or service benefits, use cases, customer value, and calls to action into clear, engaging motion graphics marketing videos.": "把产品或服务的核心卖点、使用场景、用户收益和行动引导转化为清晰有吸引力的 MG 营销视频。",
    "Break abstract knowledge, complex concepts, and technical information into understandable structures, explained clearly with icons, infographics, and motion graphics.": "把抽象知识、复杂概念和专业信息拆解成易理解的结构，通过图标、信息图和 MG 动效完成清晰讲解。",
    "Turn learning objectives, knowledge structures, teaching steps, and key points into well-paced motion graphics lessons that are easy to learn from and review.": "把课程目标、知识结构、教学步骤和重点内容转化为节奏清楚、便于学习和复习的 MG 教学视频。",
    "Turn policies, eligibility, application requirements, documents, steps, and official channels into accurate, professional, and accessible public service motion graphics videos.": "把政策依据、适用对象、办理条件、材料步骤和官方渠道转化为准确、庄重、易懂的 MG 公共服务视频。",
    "Use an AI presenter to explain product positioning, key benefits, use cases, promotions, and calls to action, creating marketing video nodes ready to play and download.": "使用数字人口播讲清商品定位、核心卖点、使用场景、优惠信息与行动引导，生成可直接播放和下载的营销视频节点。",
    "Create AI presenter videos around your personal brand, opinions, expertise, and content series, with a consistent persona, natural delivery, and stable on-camera presence.": "围绕个人定位、观点表达、知识分享和内容栏目，生成具有人设一致性、自然语气与稳定镜头表现的数字人口播视频。",
    "Use an AI presenter to explain company positioning, core business, strengths, case studies, and brand vision in a professional and credible corporate video.": "使用数字人讲解企业定位、主营业务、核心优势、案例与品牌愿景，形成专业、可信的企业宣传视频。",
    "Use an AI presenter to explain course material, training steps, and key points in structured, natural, easy-to-follow educational videos.": "使用数字人讲解课程知识、培训步骤和重点内容，生成结构清晰、表达自然、便于学习的教学视频。",
    "Use a public service AI presenter to accurately explain policy eligibility, benefits, required documents, procedures, deadlines, and official contact channels.": "使用公共服务数字人准确播报政策对象、核心权益、办理材料、流程、时限和官方咨询渠道。",
